Q: Using struct id in swiftui list A: <pre><code>import Foundation

struct User: Codable, Identifiable {
    let id = UUID()
    var name: String
    var isOnline: Bool = false
    var lastSeen: Date = Date()
}
import SwiftUI

struct RegistrationView: View {
    @State private var username: String = &quot;&quot;
    @EnvironmentObject var appState: AppState

    var body: some View {
        VStack(spacing: 30) {
            Text(&quot;Звук Тут&quot;)
                .font(.largeTitle)
                .bold()

            TextField(&quot;Введите ваше имя&quot;, text: $username)
                .textFieldStyle(RoundedBorderTextFieldStyle())
                .multilineTextAlignment(.center)

            Button(action: {
                guard !username.isEmpty else { return }
                appState.currentUser = User(name: username)
                appState.isLoggedIn = true 


            }) {
                Text(&quot;Начать общение&quot;)
                    .frame(minWidth: 200, minHeight: 44)
                    .background(Color.blue)
                    .foregroundColor(.white)
                    .cornerRadius(10)
            }
        }
        .padding(40)
    }
}
</code></pre>

Q: java.lang.ClassCastException: cannot be cast to org.openqa.selenium.WebElement using executeScript() to return shadowRoot from shadowHost A: <p>Try using the following <code>getShadowRootElement()</code> method to get the WebElement of the Shadow-root.</p>
<pre><code>public WebElement getShadowRootElement(WebElement shadowHost) {
    WebElement returnObj = null;
    Object shadowRoot = ((JavascriptExecutor) driver).executeScript(&quot;return arguments[0].shadowRoot&quot;, shadowHost);
    if (shadowRoot instanceof WebElement) {
        // ChromeDriver 95
        returnObj = (WebElement) shadowRoot;
    } else if (shadowRoot instanceof Map) {
        // ChromeDriver 96+
        Map&lt;String, Object&gt; shadowRootMap = (Map&lt;String, Object&gt;) shadowRoot;
        String shadowRootKey = (String) shadowRootMap.keySet().toArray()[0];
        String id = (String) shadowRootMap.get(shadowRootKey);
        RemoteWebElement remoteWebElement = new RemoteWebElement();
        remoteWebElement.setParent((RemoteWebDriver) driver);
        remoteWebElement.setId(id);
        returnObj = remoteWebElement;
    } else {
        System.out.println(&quot;Unexpected return type for shadowRoot in getShadowRootElement()&quot;);
    }
    return returnObj;
}
</code></pre>
